mapper.insert:
INSERT INTO material_analysis_batches (
    user_id, course_id, status, item_count, est_min_seconds, est_max_seconds, est_basis
) VALUES (
    #{userId}, #{courseId}, #{status}, #{itemCount}, #{estMinSeconds}, #{estMaxSeconds}, #{estBasis}
)

INSERT INTO material_analysis_batch_items (
    batch_id, user_id, position, filename, size_bytes, extension, upload_state,
    est_min_seconds, est_max_seconds, est_basis, message
) VALUES (
    #{batchId}, #{userId}, #{position}, #{filename}, #{sizeBytes}, #{extension}, #{uploadState},
    #{estMinSeconds}, #{estMaxSeconds}, #{estBasis}, #{message}
)

mapper.select:
SELECT * FROM material_analysis_batch_items
 WHERE batch_id = #{batchId} AND user_id = #{userId}
 ORDER BY position ASC, item_id ASC

SELECT * FROM material_analysis_batches
 WHERE user_id = #{userId} AND status IN ('STAGED', 'UPLOADING', 'ANALYZING')
 AND course_id = #{courseId}
 ORDER BY batch_id DESC
 LIMIT #{limit}

SELECT * FROM material_analysis_batch_items
 WHERE user_id = #{userId} AND material_id IN
#{id}

mapper.update:
UPDATE material_analysis_batches
   SET status = #{status},
       started_at = COALESCE(started_at, #{startedAt}),
       finished_at = #{finishedAt}
 WHERE batch_id = #{batchId} AND user_id = #{userId}

UPDATE material_analysis_batches
   SET est_min_seconds = #{estMinSeconds}, est_max_seconds = #{estMaxSeconds}, est_basis = #{estBasis}
 WHERE batch_id = #{batchId} AND user_id = #{userId}
